/*
 * A138158  Triangle read by rows: T(n,k) is the number of ordered trees with
 *          n edges and path length k; 0 <= k <= n(n+1)/2.
 * https://oeis.org/A138158
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn, tabf
 * Formula:   a(n) is the flattened triangular array T(r,k) of ordered trees
 *            with * r edges and path length k. The triangle is generated by
 *            the recurrence * P[0] = 1, P[n] = t * Σ_{j=0}^{n-1} P[j] *
 *            P[n-1-j] * t^(n-1-j), * and the coefficient of t^k in P[n]
 *            equals T(n,k)
 * Range:     u8 n <= 144, u16 n <= 498, u32 n <= 2111, u64 n <= 9918,
 *            u128 n <= 9918, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* SPDX-License-Identifier: GPL-2.0-or-later */
#include <stdlib.h>
#include <stdint.h>

/* static helpers and storage for the triangular table */
static seq_t **rows = NULL;        /* pointers to rows 0 .. size-1 */
static size_t *row_lengths = NULL; /* number of coefficients in each row */
static idx_t *cumulative = NULL;   /* cumulative counts of elements up to each row */
static size_t size = 0;            /* number of rows currently stored */

/* Build rows until the global index n is covered by the table */
static void ensure_up_to(idx_t n)
{
    if (cumulative == NULL) {
        cumulative = (idx_t*)calloc(1, sizeof(idx_t));
        if (!cumulative) exit(1);
        cumulative[0] = 0;
    }

    /* add rows until cumulative[size] > n */
    while (cumulative[size] <= n) {
        size_t r = size;                             /* new row index */
        size_t len = r * (r + 1) / 2 + 1;            /* number of coefficients */

        seq_t *row = (seq_t*)calloc(len, sizeof(seq_t));
        if (!row) exit(1);

        /* enlarge storage for rows, lengths and cumulative array */
        rows = (seq_t**)realloc(rows, (size + 1) * sizeof(seq_t*));
        if (!rows) exit(1);
        row_lengths = (size_t*)realloc(row_lengths, (size + 1) * sizeof(size_t));
        if (!row_lengths) exit(1);
        cumulative = (idx_t*)realloc(cumulative, (size + 2) * sizeof(idx_t));
        if (!cumulative) exit(1);

        rows[size] = row;
        row_lengths[size] = len;

        /* compute P[r] from the recurrence */
        if (r == 0) {
            row[0] = 1;                                 /* P[0] = 1 */
        } else {
            for (size_t j = 0; j < r; ++j) {
                size_t shift = r - j;                   /* overall index shift */
                seq_t *rowj = rows[j];
                seq_t *rowk = rows[r - 1 - j];
                size_t lenj = row_lengths[j];
                size_t lenk = row_lengths[r - 1 - j];

                for (size_t a = 0; a < lenj; ++a) {
                    seq_t val1 = rowj[a];
                    if (val1 == 0) continue;
                    for (size_t b = 0; b < lenk; ++b) {
                        seq_t val2 = rowk[b];
                        if (val2 == 0) continue;
                        row[a + b + shift] += val1 * val2;
                    }
                }
            }
        }

        /* update cumulative count */
        cumulative[size + 1] = cumulative[size] + (idx_t)len;
        ++size;
    }
}

/* Public routine to fetch the nth element of the flattened triangle. */
seq_t a(idx_t n)
{
    ensure_up_to(n);

    /* locate the row containing global index n */
    size_t r = 0;
    while (cumulative[r + 1] <= n) ++r;

    idx_t offset = n - cumulative[r];
    return rows[r][offset];
}
